  function renderWindMatrix(){
    const selectedMatrixId=selected()?.windComparison?.matrixId,matrix=library.windMatrices.find(m=>m.id===selectedMatrixId)??library.windMatrices.at(-1);
    if(!matrix){$('wind-matrix-results').textContent=L('准备试验 → 小矩阵。预先固定三种子和两个方向，失败与未执行分开；它是有界敏感性样本，不是天气可靠性概率。','Prepare trial → Small matrix. Three seeds and two directions are declared in advance; failed and unexecuted cases are separate. This bounded sensitivity sample is not atmospheric reliability.');return;}
    const summary=summarizeWindMatrix(matrix,library.records);$('wind-matrix-results').dataset.summary=JSON.stringify(summary);
    const spread=d=>d.n?fmt(d.median,4)+' / '+fmt(d.max,4):'—';
    const rows=summary.groups.map(g=>'<tr><th>'+esc(directionLabel(g.direction))+' · '+g.role+'</th><td>'+g.stableLandings+'/'+g.attempted+L(' 已执行',' attempted')+'<br>'+L('未执行 ','Not run ')+g.notRun+'</td><td>'+g.completeWindows+'/'+g.attempted+'</td><td>'+spread(g.distributions.heightRmseM)+'</td><td>'+spread(g.distributions.windowGasKg)+'</td><td>'+spread(g.distributions.totalGasKg)+'</td><td>'+fmt(g.distributions.totalAllocationLimitedS.max,3)+' / '+fmt(g.distributions.controllerLimitedS.max,3)+'</td></tr>').join('');
    const cases=matrix.rows.map(row=>'<tr><th>seed '+row.seed+' · '+esc(directionLabel(row.direction))+'</th>'+[['A',row.baselineId],['B',row.candidateId]].map(([role,id])=>{const r=library.records.find(x=>x.id===id);return '<td>'+(r?'<button type="button" data-lr-wind-result="'+esc(r.id)+'">'+role+' · '+esc(reasonNames[r.reason]?L(...reasonNames[r.reason]):r.reason)+'</button>':L('未执行','Not run'))+'</td>';}).join('')+'</tr>').join('');
    $('wind-matrix-results').innerHTML='<p class="rc-help">'+esc(matrix.plan.profile)+' · '+matrix.plan.seeds.join(' / ')+' · '+esc(matrix.plan.frozen.supplyMode)+' · '+L('配对完成/计划 ','Pairs attempted/planned ')+summary.attemptedPairs+'/'+summary.plannedPairs+' · '+L('均落稳且窗口完整 ','Qualified paired windows ')+summary.qualifiedPairs+'</p><table><thead><tr><th>'+L('方向 / 控制器','Direction / law')+'</th><th>'+L('落稳 / 执行','Landed / attempted')+'</th><th>'+L('完整窗口','Full window')+'</th><th>'+L('高度 RMSE 中位 / 最大 m','Height RMSE median / max m')+'</th><th>'+L('同窗气量 中位 / 最大 kg','Window gas median / max kg')+'</th><th>'+L('全任务气量 中位 / 最大 kg','Full-task gas median / max kg')+'</th><th>'+L('分配 / 控制图受限 最大 s','Allocation / graph limiting max s')+'</th></tr></thead><tbody>'+rows+'</tbody></table><p class="rc-help">'+L('分布含所有完整窗口，包括随后落地失败的记录。全任务气量含失败/取消的不同持续时间，不能据此选出更省气的赢家。成功比例仅描述这些预先声明的情形；静风种子是同一零风工况的重复，不能当独立风样本。','Distributions include every complete window, including later failed landings. Full-task gas includes different durations from failure/cancellation and cannot alone identify a more efficient winner. Success fractions describe only these predeclared cases; calm seeds repeat identical zero wind and are not independent wind samples.')+'</p><details open><summary>'+L('逐情形结果 · 选择失败或尾部回看','Per-case results · inspect failure or tails')+'</summary><table><thead><tr><th>'+L('风序列','Wind sequence')+'</th><th>A</th><th>B</th></tr></thead><tbody>'+cases+'</tbody></table><pre class="rc-record-details">'+esc(JSON.stringify({tails:summary.tails,source:matrix.plan.frozen.initialStateLabel,identity:matrix.plan.frozen.identity,notRunPairs:summary.notRunPairs},null,2))+'</pre></details>';
  }
