  async function action(name){try{
    if(name==='pd'||name==='pi'){$('algorithm').value=JSON.stringify(name==='pd'?HEIGHT_TEMPLATES.pd:HEIGHT_TEMPLATES.filteredPI,null,2);validateDraft({persist:true});}
    else if(name==='save'){const a=validateDraft({persist:true}).algorithm;if(!library.algorithms.some(x=>contentLabel(x)===contentLabel(a)))library.algorithms.push(a);save();render();}
    else if(name==='copy')loadSelectedDraft({duplicate:true});else if(name==='live')live();else if(name==='liveRerun')live(true);else if(name==='numeric')numeric('run');else if(name==='windRun')numeric('wind-pair');else if(name==='windMatrix')numeric('wind-matrix');else if(['rerun','compare','scan','validate'].includes(name))numeric(name);else if(name==='cancel')cancel();
    else if(name==='load'){const r=selected();if(r){$('algorithm').value=JSON.stringify(r.algorithm.algorithm,null,2);validateDraft({persist:true});}}
    else if(name==='export')download({...library,attempts,persistence:persistence.snapshot(),editorText:$('algorithm').value,protectedRaw:loaded.protectedRaw,protectedDraftRaw:draftRaw},'roadster-landing-research.json');
    else if(name==='one'){if(selected())download(selected(),selected().id+'.json');}
    else if(name==='protected')download({library:loaded.protectedRaw,draft:draftRaw,database:archiveStore?.getProtectedRaw()??null},'roadster-landing-protected-raw.json');
  }catch(error){message=L('操作未完成：','Action not completed: ')+error.message;notify(message,'warning');paintStatus();}}
