  const importFile=async e=>{try{if(!archiveReady)throw Error(L('已有任务库仍在读取，请稍候再导入。','The existing task archive is loading; retry the import when it is ready.'));const file=e.target.files?.[0];if(!file)return;if(file.size>32*1024*1024)throw Error('Import exceeds 32 MiB');const incoming=parseLandingArchive(await file.text()),merged=new Map(library.records.map(r=>[r.id,r]));for(const r of incoming.records){const old=merged.get(r.id);if(old&&contentLabel(old)!==contentLabel(r))throw Error('Record ID collision; original remains intact');merged.set(r.id,r);}const mergedAttempts=new Map(attempts.map(a=>[a.id,a]));for(const a of incoming.attempts??[]){const old=mergedAttempts.get(a.id);if(old&&contentLabel(old)!==contentLabel(a))throw Error('Attempt ID collision; original remains intact');mergedAttempts.set(a.id,a);}const mergedStudies=new Map((library.studies??[]).map(s=>[s.id,s]));for(const study of incoming.studies??[]){const old=mergedStudies.get(study.id);if(old&&contentLabel(old)!==contentLabel(study))throw Error('Study ID collision; original remains intact');mergedStudies.set(study.id,study);}const mergedMatrices=new Map((library.windMatrices??[]).map(m=>[m.id,m]));for(const matrix of incoming.windMatrices??[]){const old=mergedMatrices.get(matrix.id);if(old&&contentLabel(old)!==contentLabel(matrix))throw Error('Wind matrix ID collision; original remains intact');mergedMatrices.set(matrix.id,matrix);}library.windMatrices=[...mergedMatrices.values()];library.studies=[...mergedStudies.values()];library.records=[...merged.values()];attempts=[...mergedAttempts.values()];for(const a of incoming.algorithms)if(!library.algorithms.some(x=>contentLabel(x)===contentLabel(a)))library.algorithms.push(a);selectedId=incoming.records.at(-1)?.id??selectedId;save();render();}catch(error){message=error.message;paintStatus();}finally{e.target.value='';}};
