  mount.addEventListener('click',click);mount.addEventListener('input',input);mount.addEventListener('change',change);$('import').addEventListener('change',importFile);const off=onLanguageChange(()=>{render();try{validateDraft();}catch{}});try{validateDraft();}catch{}render();
  return{setPresentation,beforeStep(input={}){return runner&&!runner.finished?runner.beforeStep(input):input;},afterStep(t){if(runner&&!runner.finished)runner.afterStep(t);},cancel,onContextChange(){if(runner&&!runner.finished&&runner.sim!==getSim())cancel('pilot_takeover');},update(){paintStatus();},getState:()=>({running:!!runner&&!runner.finished,numericRunning:!!job,recordCount:library.records.length,selectedId,presentation,result:selected()?{id:selected().id,status:selected().status,reason:selected().reason}:null,persistence:persistence.snapshot(),live:runner?.getState()??null,exitContract:copy(exitContract),studyCount:library.studies.length,windMatrixCount:library.windMatrices.length,archiveReady,archiveBackend:archiveAvailable?'indexeddb':'legacy-localstorage'}),getRecords:()=>copy(library.records),dispose(){if(disposed)return;disposed=true;cancel();if(worker){recordAttempt('cancelled','Panel disposed before Worker returned; terminal state unavailable');save();worker.terminate();worker=null;job=null;}archiveStore?.close();off();mount.removeEventListener('click',click);mount.removeEventListener('input',input);mount.removeEventListener('change',change);$('import').removeEventListener('change',importFile);}};
